fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Since all three vectors have the same length, we can iterate over their indices safely.
    let len = dst.len();

    // Pre-allocate a vector with capacity to hold the result.
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        if mask[i] {
            // If mask at i is true, take element from src
            result.push(src[i]);
        } else {
            // Otherwise take element from dst
            result.push(dst[i]);
        }
    }

    result
}